def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    S = data[1]
    C = list(map(int, data[2:]))

    ANS = 10**50

    for i in range(N - 1):
        if S[i] == S[i + 1]:
            continue

        cost = 0
        # Calculate cost to make S[i] and S[i+1] the same
        if S[i] == '0':
            cost += C[i + 1]
        else:
            cost += C[i]

        # Calculate cost to ensure all other pairs are different
        for j in range(i):
            if S[j] == S[j + 1]:
                cost += min(C[j], C[j + 1])

        for j in range(i + 1, N - 1):
            if S[j] == S[j + 1]:
                cost += min(C[j], C[j + 1])

        ANS = min(ANS, cost)

    print(ANS)
